from media.config.limits import MAX_UPLOAD_BYTES
import os
import re


def chunk_path_0(root, name):
    return os.path.join(root, "upload", name)


def count_upload_1(items):
    total = 0
    for item in items:
        total += len(item)
    return total


def clean_chunk_2(text):
    text = text.strip().lower()
    return re.sub(r"\s+", "-", text)



def too_big(n):
    return n > MAX_UPLOAD_BYTES

